/* Auto-generated 5x7 font, cell 6x8, column-major (bit0 = top row).
   Glyphs are printable ASCII 32..127; lowercase is folded to uppercase by oled.c */
#ifndef __OLED_FONT_H
#define __OLED_FONT_H

#include <stdint.h>

#define OLED_FONT_W 6
#define OLED_FONT_H 8
#define OLED_FONT_FIRST 32
#define OLED_FONT_LAST 127

extern const uint8_t oled_font6x8[];

#endif /* __OLED_FONT_H */
